package com.sliverzfx.gothicquest

/** Archolos v1.2.2 extracted item snapshot. Acquisition and later-patch balance are not verified. */
internal object ArcholosToolsData {
    const val sourceVersion = "1.2.2"
    private data class Item(val code: String, val title: String, val group: String,
        val body: String, val source: String, val category: CodeCategory, val showInItems: Boolean)
    private val catalog: List<Item> by lazy { buildList {
        addAll(items0())
        addAll(items1())
        addAll(items2())
        addAll(items3())
        addAll(items4())
        addAll(items5())
        addAll(items6())
