        addAll(items33())
        addAll(items34())
        addAll(items35())
        addAll(items36())
        addAll(items37())
    } }

    val codes: List<ToolReferenceEntry> by lazy { generalCodes + catalog.map { item ->
        ToolReferenceEntry("arch_code_${item.code}", item.group, "Spawn ${item.title}",
            item.body + "\nSpawns an exported object nearby. Pick it up to add it to inventory.",
            command = "insert ${item.code}", source = item.source, codeCategory = item.category)
    } }
    val items: List<ToolReferenceEntry> by lazy { catalog.filter { it.showInItems }.map { item ->
        ToolReferenceEntry("arch_item_${item.code}", item.group, item.title,
            item.body + "\nExport ID: ${item.code}. Acquisition is not verified.", source = item.source)
    } }
    fun entries(section: ToolSection): List<ToolReferenceEntry> = when (section) {
        ToolSection.MARVIN_CODES -> codes
        ToolSection.USEFUL_TIPS -> tips
        ToolSection.ITEMS -> items
    }

    private val generalCodes = listOf(
        ToolReferenceEntry("arch_enable", "SETUP", "Enable Marvin mode", "Open the character/status screen (normally B), type marvin, then close that screen.", command = "marvin", source = "https://github.com/auronen/CoM-itemlist/blob/master/README.md", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("arch_console", "SETUP", "Open the console", "With Marvin mode active, press F2. Enter an insert command and press Enter; F2 closes the console.", command = "F2", source = "https://github.com/auronen/CoM-itemlist/blob/master/README.md", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("arch_disable", "SETUP", "Disable Marvin mode", "Open the character/status screen, type 42 and close it. This disables debug mode but does not undo earlier changes.", command = "42", source = "https://www.worldofgothic.com/gothic2/?go=g2cheats", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("arch_god", "CONSOLE COMMANDS", "God mode", "Toggles the Gothic II engine invulnerability cheat. Enter it again to turn it off.", command = "cheat god", source = "https://www.worldofgothic.com/gothic2/?go=g2cheats", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("arch_full", "CONSOLE COMMANDS", "Restore health and mana", "Refills current health and mana using the Gothic II engine console.", command = "cheat full", source = "https://www.worldofgothic.com/gothic2/?go=g2cheats", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("arch_abilities", "CONSOLE COMMANDS", "Edit hero attributes", "Opens the Gothic II engine attribute editor. Changes are saved with the character; keep a separate save before editing.", command = "edit abilities", source = "https://www.worldofgothic.com/gothic2/?go=g2cheats", codeCategory = CodeCategory.GENERAL),
    )
    val tips: List<ToolReferenceEntry> = listOf(
        ToolReferenceEntry("arch_tip_version", "REFERENCE", "Check the reference version", "Item IDs and numeric values come from the v1.2.2 item export. Later patches and other mods may change them. This is a source snapshot, not a claim that every object can be obtained normally.", source = "https://github.com/auronen/CoM-itemlist/blob/master/README.md"),
        ToolReferenceEntry("arch_tip_search", "REFERENCE", "Search names and insert IDs", "Search supports item names, group labels, descriptions and full insert commands. Names can be shared by several variants; the insert ID identifies the precise exported object.", source = "https://github.com/auronen/CoM-itemlist/blob/master/instanceNameList.txt"),
        ToolReferenceEntry("arch_tip_requirements", "EQUIPMENT", "Read the equip requirement", "Archolos exports include strength, dexterity, mana and even health requirements. Read the specific card instead of assuming that every melee weapon requires strength.", source = "https://github.com/auronen/CoM-itemlist/blob/master/ITM_CAT_NF.md"),
        ToolReferenceEntry("arch_tip_piercing", "EQUIPMENT", "Armor piercing is a separate stat", "Many weapons list armor piercing as well as damage. The combined armor-piercing / combat-bonus field is preserved as a combined field rather than counted twice.", source = "https://github.com/auronen/CoM-itemlist/blob/master/ITM_CAT_NF.md"),
        ToolReferenceEntry("arch_tip_upgrades", "ARMOR", "Compare exact armor variants", "Enhanced and superior armor variants have separate IDs and protection values. Search the armor name in Codes to compare all variants, including NPC outfits.", source = "https://github.com/auronen/CoM-itemlist/blob/master/ITM_CAT_ARMOR.md"),
        ToolReferenceEntry("arch_tip_belts", "ACCESSORIES", "Some belt bonuses are conditional", "Certain belts give extra bonuses only above a trained attribute threshold. Those additional bonuses appear below a condition on the card; they are not unconditional base bonuses.", source = "https://github.com/auronen/CoM-itemlist/blob/master/ITM_CAT_MAGIC.md"),
        ToolReferenceEntry("arch_tip_sets", "ACCESSORIES", "Check matching accessory sets", "Some ring and amulet effects depend on additional matching pieces. A single item card does not mean every displayed conditional bonus is active while wearing that item alone.", source = "https://github.com/auronen/CoM-itemlist/blob/master/ITM_CAT_MAGIC.md"),
        ToolReferenceEntry("arch_tip_armor_sets", "ACCESSORIES", "Match belts with armor", "Several belts have additional effects that require a particular armor family. Read the matching armor condition before comparing them.", source = "https://github.com/auronen/CoM-itemlist/blob/master/ITM_CAT_MAGIC.md"),
        ToolReferenceEntry("arch_tip_temporary", "POTIONS", "Temporary and lasting bonuses differ", "A potion with a duration and a temporary-effect note should not be treated as a lasting attribute increase. Permanent elixirs and ordinary recovery potions have different exported effects.", source = "https://github.com/auronen/CoM-itemlist/blob/master/ITM_CAT_POTION.md"),
        ToolReferenceEntry("arch_tip_recovery", "POTIONS", "Recovery can use percentages", "Some health and mana potions restore a percentage rather than a fixed number of points. Other potions recover points over time; their interval is stated on the card.", source = "https://github.com/auronen/CoM-itemlist/blob/master/ITM_CAT_POTION.md"),
        ToolReferenceEntry("arch_tip_healing", "MAGIC", "Healing spells can scale with mana", "The export includes healing spells costing 20% of maximum mana and healing for a multiple of maximum mana. Those percentages are not fixed healing-point values.", source = "https://github.com/auronen/CoM-itemlist/blob/master/ITM_CAT_RUNE.md"),
        ToolReferenceEntry("arch_tip_summon", "MAGIC", "Summoning has a limit", "Summoning entries in this export specify a limit of one active summoned creature. Accessories can separately improve the creature's damage, health or resistance.", source = "https://github.com/auronen/CoM-itemlist/blob/master/ITM_CAT_RUNE.md"),
        ToolReferenceEntry("arch_tip_crafting", "CRAFTING", "Recipes have skill requirements", "Weapon and potion recipes can require rookie, skilled or master crafting ability. Possessing an inserted recipe does not by itself establish that the character meets its requirement.", source = "https://github.com/auronen/CoM-itemlist/blob/master/ITM_CAT_DOCS.md"),
        ToolReferenceEntry("arch_tip_quest", "QUEST ITEMS", "Inserting an object is not completing a quest", "The export contains story objects and documents as well as equipment. An inserted copy does not recreate conversations, journal updates or other quest events. Keep a separate save when troubleshooting.", source = "https://github.com/auronen/CoM-itemlist/blob/master/ITM_CAT_NONE.md"),
        ToolReferenceEntry("arch_tip_value", "TRADING", "Base value is not a shop quote", "The exported Value field is shown as base value. It is not a promise of a merchant's buying or selling price.", source = "https://github.com/auronen/CoM-itemlist/blob/master/README.md"),
    )

